27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "household_size")
67	    private Integer householdSize;
68	
69	    @Column(name = "postcode")
70	    private String postcode;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    /**
79	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
80	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
81	     */
82	    private static final Map<String, String> CITY_REGION = Map.of(
83	        "Sydney", "NSW",
84	        "Melbourne", "VIC",
85	        "Brisbane", "QLD");
86	
87	    /**
88	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
89	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
90	     */
91	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
92	        "NSW", new int[] {2000, 2099},
93	        "VIC", new int[] {3000, 3099},
94	        "QLD", new int[] {4000, 4099});
95	
96	    public String getAddress() {
97	        return this.address;
98	    }
99	
100	    public void setAddress(String address) {
101	        this.address = address;
102	    }
103	
104	    public String getCity() {
105	        return this.city;
106	    }
107	
108	    public void setCity(String city) {
109	        this.city = city;
110	    }
111	
112	    public String getTelephone() {
113	        return this.telephone;
114	    }
115	
116	    public void setTelephone(String telephone) {
117	        this.telephone = telephone;
118	    }
119	
120	    public String getEmail() {
121	        return this.email;
122	    }
123	
124	    public void setEmail(String email) {
125	        this.email = email;
126	    }
127	
128	    public LocalDate getRegistrationDate() {
129	        return this.registrationDate;
130	    }
131	
132	    public void setRegistrationDate(LocalDate registrationDate) {
133	        this.registrationDate = registrationDate;
134	    }
135	
136	    public String getCustomerCode() {
137	        return this.customerCode;
138	    }
139	
140	    public void setCustomerCode(String customerCode) {
141	        this.customerCode = customerCode;
142	    }
143	
144	    /**
145	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
146	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). Derived
147	     * from the owner's own customer code and registration date; {@code null} when either is absent.
148	     *
149	     * @return the membership number, or {@code null} when it cannot be derived
150	     */
151	    public String getMembershipNumber() {
152	        if (this.customerCode == null || this.registrationDate == null) {
153	            return null;
154	        }
155	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
156	    }
157	
158	    /**
159	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
160	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
161	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
162	     *
163	     * @return the membership level, an integer from 1 to 3
164	     */
165	    public Integer getMembershipLevel() {
166	        int level = 1;
167	        boolean hasEmail = this.email != null && !this.email.isBlank();
168	        if (hasEmail) {
169	            level++;
170	        }
171	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
172	        if (hasNoNamesakes) {
173	            level++;
174	        }
175	        return Math.min(level, 3);
176	    }
177	
178	    /**
179	     * The owner's locality, the canonical region string. It is derived by looking up the
180	     * {@link #getPostcode() postcode} by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
181	     * and only falling back to the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
182	     * Brisbane->QLD) when the postcode is absent or in no known range. Returns {@code 'UNKNOWN'}
183	     * when neither the postcode nor the city resolves to a region. Preferring the postcode returns
184	     * the same region for known cities but disambiguates cities that share a name.
185	     *
186	     * @return the canonical region string, or {@code 'UNKNOWN'}
187	     */
188	    public String getLocality() {
189	        String region = regionFromPostcode();
190	        if (region != null) {
191	            return region;
192	        }
193	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
194	    }
195	
196	    /**
197	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
198	     * absent, not a 4-digit number, or in no known range.
199	     *
200	     * @return the matching region, or {@code null}
201	     */
202	    private String regionFromPostcode() {
203	        if (this.postcode == null) {
204	            return null;
205	        }
206	        int value;
207	        try {
208	            value = Integer.parseInt(this.postcode.trim());
209	        }
210	        catch (NumberFormatException ex) {
211	            return null;
212	        }
213	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
214	            int[] range = entry.getValue();
215	            if (value >= range[0] && value <= range[1]) {
216	                return entry.getKey();
217	            }
218	        }
219	        return null;
220	    }
221	
222	    /**
223	     * The owner's preferred contact channel, derived from the owner's details. Returns
224	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
225	     *
226	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
227	     */
228	    public String getContactPreference() {
229	        boolean hasEmail = this.email != null && !this.email.isBlank();
230	        return hasEmail ? "EMAIL" : "PHONE";
231	    }
232	
233	    /**
234	     * The owner's identity key, the single derived value used for duplicate detection. It is the
235	     * owner's normalized telephone, email (empty when absent) and household id joined with
236	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
237	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
238	     * are equal, so two members of the same household with different telephones differ here and are
239	     * both allowed.
240	     *
241	     * @return the derived identity key
242	     */
243	    public String getIdentityKey() {
244	        return (this.telephone == null ? "" : this.telephone) + "|"
245	            + (this.email == null ? "" : this.email) + "|"
246	            + (this.householdId == null ? "" : this.householdId);
247	    }
248	
249	    public String getHouseholdId() {
250	        return this.householdId;
251	    }
252	
253	    public void setHouseholdId(String householdId) {
254	        this.householdId = householdId;
255	    }
256	
257	    public Integer getNamesakeCount() {
258	        return this.namesakeCount;
259	    }
260	
261	    public void setNamesakeCount(Integer namesakeCount) {
262	        this.namesakeCount = namesakeCount;
263	    }
264	
265	    public Integer getHouseholdSize() {
266	        return this.householdSize;
267	    }
268	
269	    public void setHouseholdSize(Integer householdSize) {
270	        this.householdSize = householdSize;
271	    }
272	
273	    public String getPostcode() {
274	        return this.postcode;
275	    }
276	
277	    public void setPostcode(String postcode) {
278	        this.postcode = postcode;
279	    }
280	
281	    public Boolean getBulkSignupWarning() {
282	        return this.bulkSignupWarning;
283	    }
284	
285	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
286	        this.bulkSignupWarning = bulkSignupWarning;
287	    }
288	
289	    /**
290	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
291	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
292	     */
293	    @PrePersist
294	    void onCreate() {
295	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
296	    }
297	
298	    /**
299	     * Resolves the effective registration date and rolls it onto a business day. An absent
300	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
301	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
302	     * becomes the following Monday, while any weekday is returned unchanged.
303	     *
304	     * <p>This is the single definition of both the defaulting and the business-day roll, used
305	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
306	     * stamps the owner and by the create endpoint that counts owners per business day.
307	     *
308	     * @param supplied the registration date from the request, or {@code null} when none was supplied
309	     * @return the effective registration date, guaranteed to fall on a business day
310	     */
311	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
312	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
313	        return switch (effective.getDayOfWeek()) {
314	            case SATURDAY -> effective.plusDays(2);
315	            case SUNDAY -> effective.plusDays(1);
316	            default -> effective;
317	        };
318	    }
319	
320	    protected Set<Pet> getPetsInternal() {
321	        if (this.pets == null) {
322	            this.pets = new HashSet<>();
323	        }
324	        return this.pets;
325	    }
326	
327	    protected void setPetsInternal(Set<Pet> pets) {
328	        this.pets = pets;
329	    }
330	
331	    public List<Pet> getPets() {
332	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
333	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
334	        return Collections.unmodifiableList(sortedPets);
335	    }
336	
337	    public void setPets(List<Pet> pets) {
338	        this.pets = new HashSet<>(pets);
339	    }
340	
341	    public void addPet(Pet pet) {
342	        getPetsInternal().add(pet);
343	        pet.setOwner(this);
344	    }
345	
346	    /**
347	     * Return the Pet with the given name, or null if none found for this Owner.
348	     *
349	     * @param name to test
350	     * @return true if pet name is already in use
351	     */
352	    public Pet getPet(String name) {
353	        return getPet(name, false);
354	    }
355	
356	    /**
357	     * Return the Pet with the given name, or null if none found for this Owner.
358	     *
359	     * @param name to test
360	     * @return true if pet name is already in use
361	     */
362	    public Pet getPet(String name, boolean ignoreNew) {
363	        name = name.toLowerCase();
364	        for (Pet pet : getPetsInternal()) {
365	            if (!ignoreNew || !pet.isNew()) {
366	                String compName = pet.getName();
367	                compName = compName.toLowerCase();
368	                if (compName.equals(name)) {
369	                    return pet;
370	                }
371	            }
372	        }
373	        return null;
374	    }
375	
376	    public Pet getPet(Integer petId) {
377	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
378	    }
379	
380	    @Override
381	    public String toString() {
382	        return new ToStringCreator(this)
383	
384	            .append("id", this.getId())
385	            .append("new", this.isNew())
386	            .append("lastName", this.getLastName())
387	            .append("firstName", this.getFirstName())
388	            .append("address", this.address)
389	            .append("city", this.city)
390	            .append("telephone", this.telephone)
391	            .toString();
392	    }
393	}
